std::string EmbeddedText(const std::string& name)
{
    for (const EmbeddedFile& f : k_files) {
        if (name == f.name) {
            std::string text;
            for (int i = 0; i < f.count; i++) {
                text += f.chunks[i];
            }
            return text;
        }
    }
    return std::string();
}

std::vector<std::string> EmbeddedNames()
{
    std::vector<std::string> names;
    for (const EmbeddedFile& f : k_files) {
        names.push_back(f.name);
    }
    return names;
}

